const stages=[['M0','Фундамент','Unity-проект, блоки, чанки и облачные проверки.','done'],['M1','Мир и графика','Генерация, PBR-материалы, блочный персонаж и вода. Оптимизация и замеры FPS продолжаются.','active'],['M2','Первый цикл выживания','Инвентарь, крафт 2×2/3×3, печь, голод, холод и сохранения уже в коде. Проверяем весь цикл в Windows.','active'],['M3','Живой мир','День, ночь и погода уже есть. Мобы, деревни и структуры — впереди.','planned'],['M4','Пять измерений','Пять прототипов ландшафта. Порталы и полноценное прохождение ещё в разработке.','planned'],['M5','Боссы и история','Пять будущих встреч и финал Новой Эры. Пока не реализованы.','planned'],['M6','Платформы и полировка','Сначала Windows. macOS и мобильные версии рассматриваем после стабилизации, без обещанных дат.','planned']];
const articles=[
{id:'world-lab',category:'Мир',date:'15 октября 2026',title:'От первого блока — к верстаку',desc:'Блочные предметы, сетка крафта и первый цикл выживания.',art:'lestingia-hero',image:'/screenshots/workbench-3x3.webp',body:[['Выложить, а не нажать волшебную кнопку','В личном инвентаре — сетка 2×2. Поставленный верстак открывает 3×3. Рецепт зависит от расположения предметов; книга выкладывает его из ваших ресурсов. Есть разделение стеков, перетаскивание и Shift-клик.'],['Одна модель — два применения','31 voxel-предмет используется и в руке, и для рендера иконки. У 18 блоков явно заданы материалы граней; всего 24 набора PBR-карт. Печь обрабатывает сырьё с топливом; её очередь пока личная, не общий контейнер.'],['Пять характеров, не пять готовых миров','В текущем срезе есть поверхности с деревьями и пещерами, огненный рельеф, парящие острова, кристаллический и хаотический ландшафты. Порталы, боссы и уникальные механики пока остаются задачами дорожной карты.']]},
{id:'cooperative',category:'Кооператив',date:'15 октября 2026',title:'Мир становится общим',desc:'Комнаты, WebSocket и сохранение правок без лишних зависимостей.',art:'skyreach',body:[['Комната вместо огромного сервера','Для первого прототипа выбраны небольшие комнаты до восьми игроков. Клиенты получают общий seed, измерение и snapshot изменений при входе.'],['Сначала сохранить, потом подтвердить','Сервер присваивает каждой принятой правке возрастающий номер ревизии. Данные записываются до рассылки подтверждения участникам. В Cloudflare это SQLite Durable Objects; в самостоятельном Node-сервере — JSON-файлы.'],['Честно о границах','Мир кооператива ограничен 128×128×256 и 4096 изменёнными ячейками. Позиции передаются клиентом: проверки досягаемости и частоты сообщений не являются полноценным античитом. Правила сервера обновлены до версии 3: два живых WebSocket-подключения проверили станции, правки и восстановление сетки крафта, курсора, печи и воздуха. Это не визуальное совместное прохождение двух копий игры — оно ещё предстоит.']]},
{id:'new-home',category:'Проект',date:'14 октября 2026',title:'Новая эра получила свой дом',desc:'Официальный сайт, честные загрузки и путь к собственным серверам.',art:'echocrypt',body:[['Место для всей вселенной','На сайте собраны измерения, статус разработки, журнал и документация. Концепт-арт помогает передать настроение, но не выдаётся за геймплей.'],['Загрузка — только когда есть что загружать','Удалён ранний предрелиз без готовых игровых архивов. Раздел загрузок проверяет GitHub Releases и проверенный индекс и показывает только опубликованные стабильные версии с готовым Windows-архивом. Неполный или черновой релиз не превращается в кнопку «Скачать».'],['Сервер принадлежит вам','Backend отделён от Unity-клиента. Для будущих владельцев серверов предоставлены Node.js, Dockerfile и инструкция HTTPS-проксирования. Обязательной привязки к нашему Cloudflare нет.']]}
];
const faqs=[
['Игра уже вышла?','Нет. Сейчас это технический срез в разработке, а не законченная игра: базовое выживание есть в коде, боссы и кампания ещё впереди. Когда будет опубликована готовая стабильная сборка с архивом для Windows, она появится в разделе загрузок.','Релиз'],
['Почему нет кнопки скачать готовую игру?','Ранний предрелиз удалён. Мы не предлагаем исходники под видом исполняемой игры. Наличие скачивания определяется настоящими готовыми GitHub Releases, а не запланированной датой.','Релиз'],
['Нужно устанавливать Unity?','Для готового Windows-билда — нет. Unity Editor нужен разработчикам проекта, но обычный игрок запускает сборку, а не редактор. Сейчас готовые сборки ещё не опубликованы.','Игра'],
['Когда будет релиз?','Подтверждённой даты нет. Дорожная карта описывает порядок этапов, а не обещанные сроки. Сначала — надёжный игровой срез и проверенные сборки.','Релиз'],
['Уже можно играть в восьмером?','Серверный протокол поддерживает до восьми соединений на комнату и проверен сетевыми тестами. Полная визуальная сессия нескольких Unity-клиентов ещё требует проверки; готовая стабильная игра пока не выпущена.','Кооператив'],
['Как работают комнаты?','Создатель выбирает режим, начинает в Лестингии, получает 32-символьный код и передаёт друзьям. Участники вводят один серверный URL и этот код. Код даёт доступ к миру — не публикуйте его.','Кооператив'],
['Могу ли я запустить свой сервер?','Да: Node-backend есть в приватном репозитории (нужен доступ), есть Dockerfile и инструкция reverse proxy. Для собственного хостинга Cloudflare, R2 и Neon не обязательны. Это пока прототип для друзей, не большой публичный survival-сервер.','Хостинг'],
['Сохраняются ли изменения мира?','В кооперативе сервер сохраняет дельту изменений. В Cloudflare — SQLite Durable Objects, в Node — JSON-файлы. Офлайн сохраняются правки мира и состояние игрока. Сетка крафта, предмет на курсоре и личная очередь печи тоже входят в сохранение.','Игра'],
['Какие системные требования?','Измеренных минимальных и рекомендуемых требований пока нет. 60 FPS — цель проекта, не подтверждённый результат. Требования будут опубликованы после тестирования готовых сборок.','Игра'],
['Что представляют собой пять измерений?','Пять прототипов генерации уже написаны. Порталы, боссы, уникальные ресурсы и механики каждого измерения пока запланированы, но не реализованы целиком.','Игра'],
['Это Minecraft или его мод?','Нет. LestingCraft: New Era — самостоятельный Unity-проект в жанре воксельной песочницы. Проект не связан с Mojang или Microsoft.','Проект'],
['Собирает ли сайт мои данные?','Здесь нет аккаунтов, рекламных трекеров или рассылки. Сервер хостинга может обрабатывать технические запросы и IP. Подробнее — в разделе конфиденциальности.','Проект']
];
let state={releases:null,releaseError:false,server:null,checkedAt:null,source:null};let journalFilter='Все';let faqFilter='Все';let currentPath='';
