const articleCard=a=>`<a class="article-card" href="/journal/${a.id}"><div class="article-image"><img src="${a.image||'/art/'+a.art+'.webp'}" alt="${a.image?'Реальный игровой кадр':'Концепт-арт для статьи'}" loading="lazy">${badge(a.category)}</div><div class="article-meta">${a.date}<span>Журнал разработки</span></div><h3>${a.title}</h3><p>${a.desc}</p><span class="text-link">Читать заметку ${icon('arrow',18)}</span></a>`;
