const shots=[{id:'world-hud',title:'Первый взгляд на Лестингию',caption:'Мир, блочная рука с предметом, хотбар и силуэт здоровья. Реальный Windows EXE.'},{id:'workbench-3x3',title:'От ресурсов — к инструментам',caption:'Настоящий верстак 3×3: расположение рецепта, результат и книга рецептов.'}];
function shotGallery(){return `<section id="gameplay" class="section wrap gameplay-section"><div class="section-head"><div><div class="eyebrow"><span></span>УЖЕ НЕ ТОЛЬКО КОНЦЕПТ</div><h2>Вот как игра<br><em>выглядит сейчас.</em></h2></div><p>Кадры из Windows-прототипа.<br>Нажми, чтобы рассмотреть.</p></div><div class="gameplay-grid">${shots.map((shot,i)=>`<button class="gameplay-shot" data-view-shot="${i}" aria-label="Открыть кадр: ${shot.title}"><div class="shot-image"><img src="/screenshots/${shot.id}.webp" alt="${shot.title}" width="1024" height="720" loading="lazy"><span class="shot-zoom">${icon('arrow',20)}</span><span class="shot-tag">WINDOWS · ИГРОВОЙ КАДР</span></div><span class="shot-description"><strong>${shot.title}</strong><small>${shot.caption}</small></span></button>`).join('')}</div><p class="capture-note">Срез от 15 октября 2026. Кадры сняты до исправления ожидания печи в автопроверке. Они показывают запущенный EXE, но не подтверждают готовность всей сборки или FPS на вашем устройстве. <a href="/downloads">Статус загрузок ↗</a></p></section>`;}
function itemShelf(){return `<section class="item-shelf wrap"><div><div class="eyebrow">СДЕЛАНО ИЗ БЛОКОВ</div><h2>Предметы.<br>А не условные значки.</h2><p>31 объёмная voxel-модель. Иконка и предмет в руке используют одну геометрию.</p></div><div class="item-shelf-grid">${[[100,'Деревянная кирка'],[101,'Каменная кирка'],[102,'Каменный топор'],[16,'Верстак'],[17,'Печь'],[110,'Лесные ягоды'],[111,'Хлеб'],[123,'Древесный уголь']].map(([id,name])=>`<figure><img src="/items/${id}.webp" alt="${name}" loading="lazy" width="192" height="192"><figcaption>${name}</figcaption></figure>`).join('')}</div><p class="capture-note">Изображения предметов — рендеры моделей, не отдельные игровые скриншоты.</p></section>`;}
function home(){return `
<section class="field-hero"><div class="wrap field-hero-grid"><div class="field-copy"><div class="eyebrow"><span></span>ДНЕВНИК ЭКСПЕДИЦИИ / 07</div><h1>Твой первый дом.<br><em>Твой новый мир.</em></h1><p>Добывай ресурсы. Собирай инструменты. Строй место, в которое захочется вернуться — вместе с друзьями.</p><div class="hero-actions"><a class="button gold" href="#gameplay">Смотреть игру ${icon('arrow',20)}</a><a class="text-link" href="/downloads">Статус сборок ↗</a></div><div class="field-tags"><span>${icon('cube',16)} Блочный мир</span><span>${icon('tool',16)} Крафт 2×2 / 3×3</span><span>${icon('users',16)} Сервер друзей</span></div><p class="field-disclaimer">Ранний Unity-прототип. Не законченная игра и не стабильный релиз.</p></div><figure class="field-window"><div class="window-bar"><span><i></i><i></i><i></i></span><small>LESTINGCRAFT / WINDOWS</small><b>07</b></div><button data-view-shot="0" aria-label="Рассмотреть реальный кадр игры"><img src="/screenshots/world-hud.webp" alt="Реальный кадр Windows-прототипа: Лестингия, блочная рука и инвентарь" width="1024" height="720" fetchpriority="high"></button><figcaption><span class="status-dot online"></span>Не иллюстрация. Запущенный игровой мир.</figcaption><div class="window-index">01 / ПЕРВАЯ ЭКСПЕДИЦИЯ</div></figure></div></section>
<div class="checkpoint-strip"><div class="wrap"><span>СОСТОЯНИЕ ПРОЕКТА</span><p><i></i> Мир и крафт работают в прототипе</p><a href="/roadmap">Дальше — проверка полного цикла ${icon('arrow',16)}</a></div></div>
${stats()}
${shotGallery()}
${itemShelf()}
<section id="vision" class="section wrap intro"><div><div class="eyebrow"><span></span>НАША ИДЕЯ</div><h2>Не просто мир.<br><em>Место для твоей истории.</em></h2></div><div><p class="lead">Первый дом в лесу. Мост над пустотой. Последний шаг перед порталом.</p><p>Мы создаём песочницу, где строительство и исследование связаны с большой дорогой через пять измерений. Сейчас закладываем фундамент: блоки, генерацию и кооператив. Базовое выживание уже в коде. История и боссы — впереди.</p><a href="/game" class="text-link">Познакомиться с проектом ${icon('arrow',18)}</a></div></section>
<section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ЗА ГРАНЬЮ ПОРТАЛА</div><h2>Каждый мир —<br>новые правила.</h2></div><p>Пять прототипов ландшафта.<br>Пять будущих глав одной истории.<br><small>Все иллюстрации — концепт-арт.</small></p></div><div class="world-tabs" role="tablist" aria-label="Измерения">${worlds.map((w,i)=>`<button role="tab" id="tab-${w.id}" aria-controls="world-feature" aria-selected="${i===0}" data-world="${w.id}"><span>${w.n}</span>${w.name}</button>`).join('')}</div><div id="world-feature" role="tabpanel" aria-labelledby="tab-lestingia">${worldFeature(worlds[0])}</div><div class="world-mini-grid">${worlds.map(w=>`<a href="/worlds/${w.id}"><span style="color:${w.color}">✦</span><small>${w.n}</small><strong>${w.name}</strong><span>↗</span></a>`).join('')}</div></div></section>
<section class="section wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ОДИН БЛОК — ТЫСЯЧИ ВОЗМОЖНОСТЕЙ</div><h2>Мир не даёт сценарий.<br>Он даёт <em>возможности.</em></h2></div><a class="text-link" href="/game">Всё об игре ${icon('arrow',18)}</a></div><div class="feature-grid">${[['cube','Строй своё','Место, которое ты назовёшь домом. Установка и удаление блоков уже есть в техническом срезе.','В прототипе'],['compass','Иди дальше','Рельеф, пещеры, острова и кристаллы. Пять разных способов увидеть горизонт.','В прототипе'],['users','Раздели приключение','Комнаты для друзей, общий seed и сохранённые правки. Серверный протокол уже проверен.','Ранний кооператив'],['spark','Встреть неизвестное','Боссы, порталы, ресурсы и история, которая объединит пять миров.','Запланировано']].map(([i,t,d,b])=>`<article class="feature-card"><div class="feature-icon">${icon(i,30)}</div>${badge(b,b==='Запланировано'?'muted':'')}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section>
<section class="coop-banner"><div class="wrap coop-inner"><div class="coop-symbol">${icon('users',72)}</div><div><div class="eyebrow">НЕ ВСЕ ПУТИ НУЖНО ПРОХОДИТЬ В ОДИНОЧКУ</div><h2>Вместе — другой мир.</h2><p>Небольшие комнаты. Общие постройки. Свои истории.<br>Сейчас — прототип для тебя и друзей. Потом — ваши серверы.</p></div><a href="/multiplayer" class="button light">Как работает кооператив ${icon('arrow',20)}</a></div></section>
<section class="section wrap"><div class="section-head"><div><div class="eyebrow"><span></span>BLOCK BY BLOCK</div><h2>Большая игра.<br><em>Честный путь к ней.</em></h2></div><p>Не обещаем дату. Показываем прогресс.<br>Сейчас: мир, крафт, выживание и комнаты друзей.</p></div><div class="progress-panel"><div class="progress-current"><span class="huge-number">M2</span><div>${badge('В работе','live')}<h3>Первый цикл выживания</h3><p>Добыча → инструменты → верстак → печь → укрытие. Проверяем весь путь, а не только отдельные функции.</p><a href="/roadmap" class="text-link">Посмотреть дорожную карту ${icon('arrow',18)}</a></div></div><div class="progress-checks"><span>${icon('check',18)} Seed и прототипы пяти ландшафтов</span><span>${icon('check',18)} Видимые грани и коллизии</span><span>${icon('check',18)} Облачные Unity-тесты</span><span class="pending">${icon('clock',18)} Greedy-мешинг и замеры FPS</span></div></div></section>
<section class="section wrap journal-preview"><div class="section-head"><div><div class="eyebrow"><span></span>ИЗ МАСТЕРСКОЙ</div><h2>Новая эра.<br>По одной заметке.</h2></div><a href="/journal" class="text-link">Весь журнал ${icon('arrow',18)}</a></div><div class="article-grid">${articles.map(articleCard).join('')}</div></section>
<section class="download-cta wrap"><div class="eyebrow"><span></span>ТВОЁ ПРИКЛЮЧЕНИЕ НАЧНЁТСЯ ЗДЕСЬ</div><h2>Первый шаг —<br><em>за порогом привычного.</em></h2><p data-release-status>Проверяем опубликованные сборки…</p><div class="hero-actions"><a class="button gold" href="/downloads">Открыть загрузки ${icon('download',20)}</a><a class="button outline" href="/community">Следить за разработкой ↗</a></div><span class="cta-star">✦</span></section>`;}
function worldFeature(w){return `<div class="world-feature"><img src="${art(w)}" alt="Концепт-арт измерения ${w.name}" loading="lazy"><div class="world-feature-shade"></div><div class="world-feature-copy"><div class="eyebrow" style="color:${w.color}">${w.n} / 05 · ${w.en}</div><h3>${w.name}</h3><p>${w.text}</p><div class="world-boss">БУДУЩИЙ ХРАНИТЕЛЬ МИРА <strong>${w.boss}</strong></div><a href="/worlds/${w.id}" class="button light">Узнать о мире ${icon('arrow',18)}</a></div></div>`;}
function worldsPage(){return `${heading('АТЛАС НОВОЙ ЭРЫ','За каждым порталом —<br><em>другая история.</em>','Пять ландшафтов уже существуют в прототипе генерации. Полноценные измерения с порталами, боссами и уникальными механиками — следующий большой путь.')}<section class="wrap section compact"><div class="atlas-grid">${worlds.map(worldCard).join('')}</div><p class="subnote">ИИ-концепт-арт: визуальное направление проекта, не скриншоты текущей игры.</p></section><section class="wrap story-callout"><span>✦</span><div><h2>Один путь через пять миров</h2><p>По замыслу каждый босс открывает дорогу дальше. Пока это концепция прогрессии: порталы, трофеи и боссы ещё не реализованы.</p></div><a href="/roadmap" class="button outline">Что впереди ↗</a></section>`;}
function worldDetail(w){const i=worlds.indexOf(w),next=worlds[(i+1)%worlds.length];return `<section class="world-detail-hero" style="--world-color:${w.color}"><img src="${art(w)}" alt="Концепт-арт: ${w.name}"><div class="world-detail-shade"></div><div class="wrap"><a href="/worlds" class="back-link">← Все измерения</a><div class="eyebrow">${w.n} / 05 · ${w.en}</div><h1>${w.name}</h1><p>${w.subtitle}</p><span class="art-label">ИИ-КОНЦЕПТ-АРТ · НЕ ГЕЙМПЛЕЙ</span></div></section><section class="section wrap world-story"><div><div class="eyebrow"><span></span>ХАРАКТЕР МИРА</div><h2>${w.tag}</h2><p class="lead">${w.text}</p><div class="info-grid"><div><small>Ландшафт</small><strong>${w.biome}</strong></div><div><small>Блоки прототипа</small><strong>${w.materials}</strong></div><div><small>Механика по замыслу</small><strong>${w.mechanic}</strong></div></div></div><aside class="boss-card" style="--world-color:${w.color}"><span class="boss-sigil">✦</span>${badge('Запланированный босс','muted')}<small>ХРАНИТЕЛЬ ИЗМЕРЕНИЯ</small><h3>${w.boss}</h3><p>Будущая награда-ключ:<br><strong>${w.reward}</strong></p><span class="subnote">Босс и его механики пока не реализованы.</span></aside></section><section class="wrap section compact"><div class="two-columns"><article class="status-card"><div class="eyebrow green">${icon('check',18)} В ПРОТОТИПЕ</div><h3>Первые черты мира</h3><p>${w.implemented}</p></article><article class="status-card"><div class="eyebrow">${icon('clock',18)} ВПЕРЕДИ</div><h3>От ландшафта к приключению</h3><p>${w.planned}</p></article></div></section><a class="next-world wrap" href="/worlds/${next.id}"><span>СЛЕДУЮЩАЯ ГЛАВА</span><strong>${next.name}</strong><span>↗</span></a>`;}
function gamePage(){return `${heading('О ПРОЕКТЕ','Мир начинается<br><em>с твоего выбора.</em>','LestingCraft: New Era — самостоятельная воксельная песочница на Unity. Исследование, строительство и путь через пять измерений — наша концепция игры.')}${shotGallery()}${itemShelf()}${stats()}<section class="section wrap two-columns"><div><div class="eyebrow"><span></span>НАШИ ЧЕТЫРЕ ОПОРЫ</div><h2>Приключение.<br>Не набор кубов.</h2><p>Хотим создать мир, в который интересно возвращаться — не ради очередной цифры, а ради нового открытия.</p></div><div class="pillar-list">${[['01','Мир, который хочется исследовать','Ландшафты, пещеры и самобытные измерения. Большие биомы, структуры и экосистемы пока в планах.'],['02','Смысл в каждом новом шаге','Задуманная цепочка: ресурсы → крафт → экипировка → портал → босс. Добыча, инструменты, верстак и печь уже в коде. Порталы и боссы — впереди.'],['03','Боссы с характером','В планах — разные арены и многофазные встречи, а не просто враги с большим запасом здоровья.'],['04','Уважение к производительности','Burst/Jobs для генерации уже подключены. Оптимизация мешей и реальные замеры FPS ещё требуют работы. Программный рендер CI не показывает производительность на вашем ПК.']].map(([n,t,d])=>`<article><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div></article>`).join('')}</div></section><section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span></span>СЕГОДНЯ И ЗАВТРА</div><h2>Концепция большая.<br>Статус — прозрачный.</h2></div></div><div class="two-columns"><div class="status-card">${badge('Технический срез','live')}<h3>Уже в коде</h3><ul class="check-list"><li>Генерация по seed и пять ландшафтов</li><li>Чанки, стриминг, видимые грани и коллизии</li><li>Блочный персонаж, добыча и строительство</li><li>45 слотов, сетка 2×2 и верстак 3×3</li><li>Печь, голод, холод, промокание и воздух</li><li>Ранний кооператив и серверные сохранения</li><li>Облачные тесты Unity и серверного протокола</li></ul></div><div class="status-card">${badge('Не выдаём за готовое','muted')}<h3>Ещё предстоит</h3><ul class="plain-list"><li>Общие контейнеры и расширение выживания</li><li>Живые биомы, мобы и структуры</li><li>Порталы, боссы и история</li><li>Greedy-мешинг, FPS и совместимость</li><li>Визуальные многопользовательские тесты</li></ul></div></div></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ИНСТРУМЕНТЫ НОВОЙ ЭРЫ</div><h2>Собираем фундамент.</h2></div><p>Разработка ведётся в GitHub.<br>Репозиторий приватный: доступ по приглашению.</p></div><div class="tech-grid">${[['UNITY 6 LTS','Движок проекта'],['BURST + JOBS','Генерация колонок'],['C#','Игровое ядро'],['WEBSOCKET','Комнаты друзей'],['CLOUDFLARE / NODE','Два способа хостинга'],['GITHUB ACTIONS','Облачные проверки']].map(([t,d])=>`<div><strong>${t}</strong><span>${d}</span></div>`).join('')}</div>${ext(REPO,'Посмотреть исходники','button outline')}</section>`;}
function downloadsPage(){return `${heading('ЦЕНТР ЗАГРУЗОК','Твоя новая эра —<br><em>с первого запуска.</em>','Только настоящие игровые сборки. Без редактора Unity на твоём компьютере. Без исходников под видом готовой игры.')}<section class="section compact wrap"><div id="release-panel" aria-live="polite">${downloadPanel()}</div><div class="two-columns download-info"><article class="status-card"><div class="feature-icon">${icon('shield',28)}</div><h3>Из официального репозитория</h3><p>Архивы загружаются напрямую из GitHub Releases. Сайт не просит ключи Cloudflare, пароли Unity или платёжные данные.</p></article><article class="status-card"><div class="feature-icon">${icon('clock',28)}</div><h3>Совместимость без догадок</h3><p>Минимальные системные требования ещё не измерены. Они будут опубликованы после тестирования готовых сборок, а не придуманы заранее.</p></article></div><div id="release-history"></div><aside class="tester-access"><div><span class="eyebrow">ДЛЯ ПРИГЛАШЁННЫХ ТЕСТЕРОВ</span><h3>Тестовый архив — не релиз</h3><p>Проверенные тестовые архивы публикуются в Artifacts завершённой Windows-задачи. Нужны вход в GitHub и доступ к приватному репозиторию. Красная задача не считается готовой сборкой.</p></div>${ext(REPO+'/actions/workflows/build.yml','Открыть проверки','button outline')}</aside></section><section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ДО ПЕРВОГО ЗАПУСКА</div><h2>Выбери свой путь.</h2></div></div><div class="three-columns">${[['01','Windows','Когда сборка появится: скачать ZIP, распаковать папку целиком и запустить LestingCraft.exe. Unity Editor не потребуется.'],['02','Кооператив','Запустить Windows-клиент, создать комнату и передать код друзьям. Браузерная версия отложена; сервер работает отдельно от клиента.'],['03','Свой сервер','Backend уже есть в исходниках. Для хостинга нужны Node.js или Docker и HTTPS для браузерных клиентов. Это отдельный сервер, не установка Unity.']].map(([n,t,d])=>`<article class="number-card"><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><a href="/hosting" class="text-link">Документация собственного сервера ${icon('arrow',18)}</a></div></section>`;}
function downloadPanel(){if(state.releases===null&&!state.releaseError)return `<div class="release-panel empty"><span class="loader"></span><h2>Проверяем релизы…</h2><p>Сверяем доступные архивы с GitHub.</p></div>`;if(state.releaseError)return `<div class="release-panel empty"><span class="empty-symbol">↻</span>${badge('Проверка недоступна','muted')}<h2>Не удалось проверить сборки</h2><p>Это не означает, что релизов нет. Можно проверить GitHub напрямую или повторить запрос позже.</p><div class="hero-actions"><button class="button gold" data-refresh-releases>Повторить проверку ↻</button>${ext(REPO+'/releases','Проверить GitHub','button outline')}</div></div>`;if(!state.releases.length)return `<div class="release-panel empty"><span class="empty-symbol">✦</span>${badge('В разработке','live')}<h2>Пока — тестовые<br>экспедиции.</h2><p>Готовой стабильной сборки пока нет. Тестовые Windows-архивы и стабильный релиз — разные вещи.<br>Когда стабильная Windows-сборка будет опубликована, она появится здесь автоматически.</p><div class="hero-actions"><a class="button gold" href="/roadmap">Что уже сделано ${icon('arrow',18)}</a>${ext(REPO+'/releases','GitHub Releases','button outline')}</div><span class="subnote">${state.source==='verified-index'?'Проверенный индекс GitHub · '+(state.checkedAt?new Date(state.checkedAt).toLocaleString('ru-RU'):''):'GitHub API · кэш до 5 минут'} · дата выхода не объявлена</span></div>`;const r=state.releases[0];return `<div class="release-panel ready"><div>${badge('Стабильная сборка','live')}<div class="eyebrow">${escape(r.tag)} · ${new Date(r.date).toLocaleDateString('ru-RU')}</div><h2>${escape(r.name)}</h2><p>Windows-архив опубликован в GitHub Releases.</p>${ext(r.url,'Описание версии')}</div><div class="platform-grid"><a class="platform-button" href="${escape(r.windows.url)}">${icon('download',32)}<strong>Windows 64-bit</strong><span>ZIP · ${size(r.windows.size)}</span></a></div></div>`;}
const size=n=>`${(n/1048576).toFixed(1)} МБ`;
function roadmapPage(){return `${heading('ДОРОЖНАЯ КАРТА','Не обещание даты.<br><em>План большой дороги.</em>','Развитие по этапам, с проверяемыми результатами. Мир, крафт и базовое выживание развиваются параллельно. Реализованный код ещё не означает законченный и проверенный релиз.')}<section class="section compact wrap"><div class="roadmap-list">${stages.map(([n,t,d,s])=>`<article class="roadmap-stage ${s}"><div class="stage-marker">${s==='done'?icon('check',24):n}</div><div class="stage-heading"><span class="eyebrow">${n} · ${s==='done'?'ЗАКРЫТО':s==='active'?'ТЕКУЩИЙ ЭТАП':'ВПЕРЕДИ'}</span><h2>${t}</h2><p>${d}</p></div>${badge(s==='done'?'Готово':s==='active'?'В работе':'Запланировано',s==='planned'?'muted':s==='active'?'live':'')}</article>`).join('')}</div><div class="status-card milestone-extra">${badge('Параллельный срез')}<h3>Кооператив для друзей</h3><p>Мультиплеер перенесён на ранний этап по решению автора. Уже есть комнаты, синхронизация правок и самостоятельный backend. Это ограниченный прототип, а не готовый сервер выживания.</p><a href="/multiplayer" class="text-link">Подробнее ${icon('arrow',18)}</a></div></section>`;}
function journalPage(){return `${heading('ЖУРНАЛ РАЗРАБОТКИ','Не за кулисами.<br><em>Рядом с мастерской.</em>','Заметки о том, что действительно появилось в проекте: решения, ограничения и следующие шаги.')}<section class="section compact wrap"><div class="filter-row" role="group" aria-label="Темы журнала">${['Все','Мир','Кооператив','Проект'].map(t=>`<button class="filter ${journalFilter===t?'active':''}" data-journal-filter="${t}">${t}</button>`).join('')}</div><div class="article-grid">${articles.filter(a=>journalFilter==='Все'||a.category===journalFilter).map(articleCard).join('')}</div><p class="subnote">Обновления публикуются после фактических изменений. Здесь нет выдуманных анонсов и отзывов.</p></section>`;}
function articlePage(a){return `${heading('ЖУРНАЛ · '+a.category.toUpperCase(),a.title,a.desc)}<article class="article-full wrap"><div class="article-meta">${a.date}<a href="/journal">← Все заметки</a></div><img src="${a.image||'/art/'+a.art+'.webp'}" alt="${a.image?'Реальный кадр верстака':'ИИ-концепт-арт к заметке'}"><span class="subnote">${a.image?'Реальный Windows EXE. Кадр не является подтверждением готовности всего релиза.':'Концепт-арт, не скриншот игрового среза.'}</span><div class="prose">${a.body.map(([t,d])=>`<h2>${t}</h2><p>${d}</p>`).join('')}<aside class="prose-note">Репозиторий — источник правды о коде. Статус этой заметки относится к техническому срезу октября 2026.</aside>${ext(REPO,'Открыть репозиторий','button outline')}</div></article>`;}
function multiplayerPage(){return `${heading('ПРИКЛЮЧЕНИЕ ВМЕСТЕ','Один seed.<br><em>Ваш общий мир.</em>','Кооперативный прототип для тебя и друзей. Без обязательных аккаунтов и без зависимости от одного хостинга.')}<section class="section compact wrap"><div class="server-status-box"><div><span class="status-dot" data-server-dot></span><strong>Сервер комнат</strong><span data-server-status>Проверяем доступность…</span></div><button class="text-link" data-copy="${SERVER}">Скопировать адрес ${icon('code',18)}</button></div><div class="three-columns steps">${[['01','Создай комнату','Укажи имя и выбери режим. Мир получает seed автоматически и начинается в Лестингии. Сервер создаст отдельную комнату.'],['02','Передай код друзьям','32-символьный код открывает доступ к миру. Сохрани его и не публикуй в открытом доступе.'],['03','Меняйте мир вместе','Сервер подтверждает и сохраняет правки, а участники видят изменения. На входе приходит snapshot.']].map(([n,t,d])=>`<article class="number-card"><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><aside class="prose-note">Серверный протокол проверен реальными WebSocket-клиентами. Готовой стабильной игровой сборки ещё нет, а полноценный визуальный тест нескольких Unity-клиентов предстоит.</aside></section><section class="section section-dark"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><span></span>КОМНАТЫ, А НЕ MMO</div><h2>Меньше обещаний.<br>Больше ясности.</h2></div></div><div class="limit-grid">${[['08','игроков в комнате'],['128 × 128','горизонтальные границы'],['256','блоков по высоте'],['4096','изменённых ячеек']].map(([v,l])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="two-columns"><div class="status-card"><h3>Что синхронизируется</h3><ul class="check-list"><li>Seed и параметры комнаты</li><li>Позиции и имена участников</li><li>Принятые изменения блоков</li><li>Snapshot мира при входе и личные сохранения</li></ul></div><div class="status-card"><h3>О чём важно помнить</h3><ul class="plain-list"><li>Нет аккаунтов, ролей и античита</li><li>Позициям клиентов пока доверяем</li><li>При обрыве нужен повторный вход</li><li>Знание кода позволяет менять мир</li></ul></div></div></div></section><section class="section wrap intro"><div><div class="eyebrow"><span></span>ВАШ МИР. ВАШ СЕРВЕР.</div><h2>Не привязываем<br>к нашему облаку.</h2></div><div><p class="lead">Cloudflare для прототипа. Node.js — для самостоятельного хостинга.</p><p>Backend отделён от игрового клиента. В будущем владельцы серверов смогут выбирать инфраструктуру и хранить свои миры. Сейчас исходники и инструкция уже доступны.</p><a href="/hosting" class="button gold">Запустить свой сервер ${icon('arrow',18)}</a></div></section>`;}
const codeBlock=(code,id)=>`<div class="code-block"><div><span>TERMINAL</span><button data-copy-code="${id}" aria-label="Скопировать команды">Копировать ⧉</button></div><pre id="${id}"><code>${escape(code)}</code></pre></div>`;
function hostingPage(){return `${heading('ДЛЯ ВЛАДЕЛЬЦЕВ СЕРВЕРОВ','Ваши друзья.<br><em>Ваша инфраструктура.</em>','Самостоятельный backend без обязательного Cloudflare, R2 или Neon. Инструкция для владельца сервера — не требование ставить Unity на ПК игрока.')}<section class="wrap section compact docs-layout"><aside class="docs-nav"><strong>СОДЕРЖАНИЕ</strong><a href="#host-node">Node.js</a><a href="#host-docker">Docker</a><a href="#host-tls">HTTPS / WebSocket</a><a href="#host-backup">Сохранения</a><a href="#host-limits">Ограничения</a>${ext(REPO+'/blob/main/Docs/Мультиплеер-и-хостинг.md','Полная документация')}</aside><div class="docs-content"><section id="host-node"><div class="eyebrow">01 / САМОСТОЯТЕЛЬНЫЙ BACKEND</div><h2>Node.js 20+ / 22 LTS</h2><p>При наличии доступа к приватному репозиторию клонируйте проект на VPS или другой машине для хостинга. Укажите постоянную директорию данных. Это серверный код, не Unity Editor.</p>${codeBlock('git clone '+REPO+'.git\ncd lestingcraft-new-era/Server\nnpm ci --omit=dev\nPORT=8787 DATA_DIR=/srv/lestingcraft-data npm start','node-code')}<details class="faq-item"><summary>Команды для Windows PowerShell</summary>${codeBlock('$env:PORT = "8787"\n$env:DATA_DIR = "C:\\lestingcraft-data"\nnpm start','powershell-code')}</details></section><section id="host-docker"><div class="eyebrow">02 / В КОНТЕЙНЕРЕ</div><h2>Docker и постоянный том</h2><p>Dockerfile есть в репозитории. Обязательно подключите том для сохранений: замена контейнера не должна удалять ваш мир.</p>${codeBlock('cd Server\ndocker build -t lestingcraft-server .\ndocker volume create lestingcraft-worlds\ndocker run -d --name lestingcraft --restart unless-stopped \\\n  -p 8787:8787 -v lestingcraft-worlds:/data lestingcraft-server','docker-code')}<p class="subnote">Node backend и протокол проверены. Запуск Docker-контейнера в среде разработки пока отдельно не проверялся.</p></section><section id="host-tls"><div class="eyebrow">03 / БЕЗОПАСНОЕ СОЕДИНЕНИЕ</div><h2>Защищённое соединение</h2><p>Для Windows-клиента рекомендуется HTTPS/WSS сервер. Вариант с Caddy: направьте DNS своего домена на VPS и откройте порты 80/443.</p>${codeBlock('play.example.com {\n    reverse_proxy 127.0.0.1:8787\n}','caddy-code')}<p>В игровом меню укажите <code>https://play.example.com</code>. Caddy проксирует WebSocket. Не выставляйте незашифрованный сервер для публичной игры.</p></section><section id="host-backup"><div class="eyebrow">04 / ЧТОБЫ МИР НЕ ИСЧЕЗ</div><h2>Сохранения и резервная копия</h2><p>Standalone хранит параметры комнат и изменения в JSON-файлах <code>DATA_DIR</code>. Остановите сервер и скопируйте всю директорию. При восстановлении верните файлы и подключитесь по прежнему коду комнаты.</p><aside class="prose-note">Код комнаты — ключ доступа. Не включайте сохранения в публичный репозиторий. Автоматический экспорт Cloudflare-комнат пока не реализован.</aside></section><section id="host-limits"><div class="eyebrow">05 / ПЕРЕД ПУБЛИЧНЫМ ХОСТИНГОМ</div><h2>Прототип, не production</h2><p>До восьми игроков и 4096 изменённых ячеек на комнату. Запись standalone JSON синхронная; большой нагрузке нужны другое хранилище и дополнительная защита. Нет авторитетной физики, ролей и античита.</p><p>Node лимитирует создание комнат по непосредственному IP. За reverse proxy один адрес может оказаться общим для всех. Не доверяйте произвольному <code>X-Forwarded-For</code> без настройки доверенных прокси.</p>${ext(REPO+'/blob/main/Docs/Мультиплеер-и-хостинг.md','Открыть подробный документ','button outline')}</section></div></section>`;}
function faqPage(){return `${heading('ПОЛЕЗНО ЗНАТЬ','Прямые вопросы.<br><em>Честные ответы.</em>','О релизе, кооперативе, системных требованиях и том, что пока только впереди.')}<section class="section compact wrap faq-section"><label class="search-box">${icon('compass',22)}<input id="faq-search" type="search" placeholder="Найти ответ…" aria-label="Поиск по вопросам"></label><div class="filter-row" role="group" aria-label="Категории вопросов">${['Все','Релиз','Игра','Кооператив','Хостинг','Проект'].map(t=>`<button class="filter ${faqFilter===t?'active':''}" data-faq-filter="${t}">${t}</button>`).join('')}</div><div id="faq-list">${faqList()}</div><div class="faq-help"><h3>Остался другой вопрос?</h3><p>Если это ошибка или техническое предложение, опишите её в GitHub Issues. В поддержку не нужно отправлять пароли или API-ключи.</p>${ext(REPO+'/issues','Открыть Issues','button outline')}</div></section>`;}
function faqList(query=''){const rows=faqs.filter(([q,a,c])=>(faqFilter==='Все'||c===faqFilter)&&(q+' '+a).toLowerCase().includes(query.toLowerCase()));return rows.length?rows.map(([q,a,c])=>`<details class="faq-item"><summary><span>${q}</span><span class="faq-plus">+</span></summary><p>${a}</p><small>${c}</small></details>`).join(''):'<div class="no-results">Ответов по этому запросу нет. Попробуй другие слова.</div>';}
function communityPage(){return `${heading('РЯДОМ С НОВОЙ ЭРОЙ','Игра ещё строится.<br><em>Но ты уже можешь быть рядом.</em>','Следить за кодом, сообщать об ошибках и предлагать идеи. Без выдуманного числа участников и несуществующих социальных ссылок.')}<section class="section compact wrap community-grid"><article class="community-main"><div class="feature-icon">${icon('code',38)}</div><h2>Мастерская проекта</h2><p>Репозиторий сейчас приватный. Приглашённые участники могут смотреть изменения, тестовые сборки и проверки. Публичные новости и кадры публикуем здесь; открытая лицензия пока не объявлена.</p>${ext(REPO,'Открыть GitHub','button gold')}</article><div class="community-side"><article class="status-card"><h3>Нашёл ошибку?</h3><p>Шаги воспроизведения, платформа, версия сборки и лог без секретов помогают больше, чем «не работает».</p>${ext(REPO+'/issues','Сообщить через Issues')}</article><article class="status-card"><h3>Есть идея для игры?</h3><p>Начни с того, какое игровое ощущение она создаёт. Новая механика должна усиливать мир, исследование или совместное приключение.</p>${ext(REPO+'/issues','Предложить идею')}</article></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ЕСТЬ КУДА РАСТИ</div><h2>Лучше по делу.<br>Лучше вместе.</h2></div></div><div class="three-columns">${[['Не обещаем лишнего','Discord, форум и регистрация сейчас не подключены. Когда появятся настоящие площадки, добавим их ссылки.'],['Не принимаем секреты','Пароли, GitHub PAT, Cloudflare и Neon API-ключи не нужны для обсуждений и обратной связи.'],['Не выдаём планы за функции','Пометки «запланировано» важны. Идеи и концепт-арт не означают, что механика уже работает в игре.']].map(([t,d])=>`<article class="status-card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section>`;}
function pressPage(){return `${heading('МЕДИА И МАТЕРИАЛЫ','История проекта.<br><em>Без лишнего шума.</em>','Краткие факты и материалы для знакомства с LestingCraft: New Era. Перед публикацией проверьте актуальное состояние разработки.')}<section class="section compact wrap two-columns"><article class="status-card"><h2>Коротко о проекте</h2><dl class="fact-list"><dt>Название</dt><dd>LestingCraft: New Era</dd><dt>Жанр</dt><dd>Воксельная песочница / приключение</dd><dt>Движок</dt><dd>Unity 6 LTS</dd><dt>Статус</dt><dd>Технический срез в разработке</dd><dt>Целевые сборки</dt><dd>Windows 64-bit</dd><dt>Дата релиза</dt><dd>Не объявлена</dd><dt>Автор репозитория</dt><dd>Timofei2506</dd></dl></article><article class="status-card"><h2>Корректное описание</h2><p id="press-description">LestingCraft: New Era — независимый Unity-проект в жанре воксельной песочницы. Его концепция объединяет строительство, исследование, пять измерений и кооператив. В прототипе есть мир, блочный персонаж, крафт, базовые механики выживания и сервер друзей. Порталы, боссы и законченная кампания ещё не готовы.</p><button class="button outline" data-copy-code="press-description">Скопировать описание ⧉</button></article></section>${shotGallery()}<section class="section wrap"><div class="section-head"><div><div class="eyebrow"><span></span>ВИЗУАЛЬНОЕ НАПРАВЛЕНИЕ</div><h2>Атмосфера пяти миров.</h2></div><p>ИИ-концепт-арт для сайта.<br>Не игровые скриншоты и не доказательство качества сборки.</p></div><div class="atlas-grid">${worlds.map(w=>`<figure class="press-art"><img src="${art(w)}" alt="ИИ-концепт-арт ${w.name}" loading="lazy"><figcaption>${w.name}<a href="${art(w)}" download>Загрузить WebP ↓</a></figcaption></figure>`).join('')}</div><aside class="prose-note">Материалы предназначены для знакомства с проектом с указанием источника. Отдельная лицензия на коммерческое использование кода и материалов не объявлена. Репозиторий приватный; доступ к нему не означает разрешение на любое использование материалов.</aside></section>`;}
function privacyPage(){return `${heading('КОНФИДЕНЦИАЛЬНОСТЬ','Без лишних данных.<br><em>Без скрытых обещаний.</em>','Техническая информация о работе этого сайта. Версия описания: 14 октября 2026.')}<section class="prose wrap section compact"><h2>Что делает сайт</h2><p>Сайт показывает информацию об игре, проверяет готовые GitHub Releases и доступность сервера кооператива через собственные API-маршруты. Нет регистрации, форм рассылки, платежей, рекламных пикселей или клиентской аналитики.</p><h2>Шрифты и изображения</h2><p>Файлы шрифтов и иллюстраций размещены вместе с сайтом. Браузер не обращается к Google Fonts за шрифтами. Концепт-арт создан с помощью ИИ и помечен отдельно от геймплея.</p><h2>Техническая обработка</h2><p>Хостинг Cloudflare может обрабатывать IP, заголовки запросов и технические сведения для доставки сайта и защиты инфраструктуры. Запросы к GitHub API выполняются серверной частью сайта; при переходе на GitHub или скачивании архива действуют правила GitHub.</p><h2>Cookies и локальное хранение</h2><p>Собственных cookies и постоянного профиля посетителя сайт не создаёт. Копирование адресов и команд обращается к буферу обмена только после нажатия кнопки.</p><h2>Игровой сервер — отдельно</h2><p>В кооперативе передаются выбранное имя, позиция и правки блоков. Сервер сохраняет параметры комнаты и изменения мира. Коды комнат дают доступ к миру; делитесь ими только с теми, кому доверяете.</p><h2>Обратная связь</h2><p>Технические вопросы можно оставить в GitHub Issues. Не публикуйте пароли, личные данные или API-токены.</p>${ext(REPO+'/issues','Открыть Issues','button outline')}</section>`;}
function notFound(){return `${heading('404 · ПО ТУ СТОРОНУ КАРТЫ','Этот путь пока<br><em>не проложен.</em>','Страница не найдена. Но вселенная LestingCraft начинается совсем рядом.')}<div class="wrap section compact"><a class="button gold" href="/">Вернуться в Лестингию ←</a></div>`;}
const routes={'/':home,'/worlds':worldsPage,'/game':gamePage,'/downloads':downloadsPage,'/roadmap':roadmapPage,'/journal':journalPage,'/multiplayer':multiplayerPage,'/hosting':hostingPage,'/faq':faqPage,'/community':communityPage,'/press':pressPage,'/privacy':privacyPage};
const titles={'/':'Пять миров. Одна новая эра','/worlds':'Вселенная','/game':'Об игре','/downloads':'Загрузки','/roadmap':'Дорожная карта','/journal':'Журнал разработки','/multiplayer':'Кооператив','/hosting':'Свой сервер','/faq':'Вопросы и ответы','/community':'Сообщество','/press':'Медиа и материалы','/privacy':'Конфиденциальность'};
function render(path=location.pathname,scroll=true){currentPath=path.replace(/\/$/,'')||'/';let page=routes[currentPath],title=titles[currentPath];const w=worlds.find(w=>currentPath==='/worlds/'+w.id);const a=articles.find(a=>currentPath==='/journal/'+a.id);if(w){page=()=>worldDetail(w);title=w.name;}if(a){page=()=>articlePage(a);title=a.title;}main.innerHTML=(page||notFound)();document.title=(title||'Страница не найдена')+' — LestingCraft: New Era';document.querySelectorAll('[data-nav]').forEach(a=>{const active=currentPath.startsWith('/'+a.dataset.nav);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');paintStatus();if(scroll){if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());else window.scrollTo(0,0);}bindReveal();}
function navigate(url){history.pushState({},'',url);render();main.focus({preventScroll:true});}
document.addEventListener('click',async e=>{const target=e.target.closest('a,button');if(!target)return;
 if(target.hasAttribute('data-view-shot')){const shot=shots[Number(target.dataset.viewShot)];const dialog=$('#media-dialog');$('#media-title').textContent=shot.title;$('#media-image').src='/screenshots/'+shot.id+'.webp';$('#media-image').alt=shot.title;$('#media-caption').textContent=shot.caption+' Срез 15 октября; не финальный релиз.';dialog.showModal();return;}
 if(target.hasAttribute('data-close-media')){$('#media-dialog').close();return;}
 if(target.id==='menu-toggle'){const menu=$('#mobile-nav');menu.hidden=!menu.hidden;target.setAttribute('aria-expanded',String(!menu.hidden));return;}
 if(target.dataset.world){const w=worlds.find(w=>w.id===target.dataset.world);$('#world-feature').innerHTML=worldFeature(w);$('#world-feature').setAttribute('aria-labelledby','tab-'+w.id);document.querySelectorAll('[data-world]').forEach(t=>t.setAttribute('aria-selected',String(t===target)));return;}
 if(target.dataset.journalFilter){journalFilter=target.dataset.journalFilter;render(currentPath,false);return;}
 if(target.dataset.faqFilter){faqFilter=target.dataset.faqFilter;render(currentPath,false);return;}
 if(target.hasAttribute('data-refresh-releases')){state.releaseError=false;state.releases=null;paintStatus();await loadReleases();return;}
 if(target.dataset.copy||target.dataset.copyCode){const text=target.dataset.copy||document.getElementById(target.dataset.copyCode)?.textContent;await copy(text);return;}
 if(target.tagName==='A'&&!target.hasAttribute('download')&&target.target!=='_blank'&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){const url=new URL(target.href,location.href);if(url.origin===location.origin){e.preventDefault();if(url.pathname===location.pathname&&url.hash){history.pushState({},'',url.pathname+url.hash);document.getElementById(url.hash.slice(1))?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}else navigate(url.pathname+url.hash);}}
});
document.addEventListener('input',e=>{if(e.target.id==='faq-search')$('#faq-list').innerHTML=faqList(e.target.value);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}const tab=e.target.closest('[data-world]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[data-world]')],i=tabs.indexOf(tab);const index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[index].focus();tabs[index].click();}});
window.addEventListener('popstate',()=>render());
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Скопировано в буфер обмена');}catch{const area=document.createElement('textarea');area.value=text;document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Скопировано':'Не удалось скопировать. Выделите текст вручную.');}}
let toastTimer;function toast(text){const box=$('#toast');box.textContent=text;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3000);}
function paintStatus(){document.querySelectorAll('[data-release-status]').forEach(el=>el.textContent=state.releaseError?'Не удалось проверить релизы. Статус доступен на GitHub.':state.releases===null?'Проверяем опубликованные сборки…':state.releases.length?'Готовая стабильная сборка опубликована. Выбери свой путь.':'Игра в разработке. Готовые стабильные сборки пока не опубликованы.');if($('#release-panel'))$('#release-panel').innerHTML=downloadPanel();if($('#release-history')&&state.releases?.length>1)$('#release-history').innerHTML=`<h2>Предыдущие стабильные версии</h2><div class="release-history">${state.releases.slice(1).map(r=>`<a href="${escape(r.url)}" target="_blank" rel="noopener"><strong>${escape(r.tag)}</strong><span>${new Date(r.date).toLocaleDateString('ru-RU')}</span><span>Открыть релиз ↗</span></a>`).join('')}</div>`;document.querySelectorAll('[data-server-status]').forEach(el=>el.textContent=state.server===null?'Проверяем доступность…':state.server?'API доступно · не означает, что игровой релиз готов':'API сейчас недоступно · попробуйте позже');document.querySelectorAll('[data-server-dot]').forEach(el=>el.classList.toggle('online',state.server===true));}
async function loadReleases(){try{const r=await fetch('/api/releases');if(!r.ok)throw Error();const d=await r.json();if(!d.available||!Array.isArray(d.releases))throw Error();state.releases=d.releases;state.checkedAt=d.checkedAt;state.source=d.source;state.releaseError=false;}catch{state.releaseError=true;}paintStatus();}
async function loadStatus(){try{const r=await fetch('/api/status');if(!r.ok)throw Error();state.server=(await r.json()).online===true;}catch{state.server=false;}paintStatus();}
let observer;function bindReveal(){observer?.disconnect();if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');observer.unobserve(entry.target);}}),{threshold:.06});document.querySelectorAll('.section-head,.feature-card,.article-card,.roadmap-stage').forEach(el=>{el.classList.add('reveal');observer.observe(el);});}
$('#media-dialog')?.addEventListener('click',e=>{if(e.target.id==='media-dialog')e.target.close();});
render(location.pathname,false);loadReleases();loadStatus();
